'use client';

import React, { useEffect, useState } from 'react';
import { useGameStore } from '../store/gameStore';
import { LandingPage } from '../components/LandingPage';
import { GameInterface } from '../components/GameInterface';
import { Dashboard } from '../components/Dashboard';

export default function GameController() {
  const { isActiveRound, totalXP } = useGameStore();
  const [mounted, setMounted] = useState(false);

  // Prevent hydration mismatch for Zustand persisted state
  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) return <div className="min-h-screen bg-gray-950 flex items-center justify-center text-cyan-400 animate-pulse">Loading Game Engine...</div>;

  // View Orchestration
  if (isActiveRound) {
    return <GameInterface />;
  }

  // If they have XP, they've played before, show Dashboard. Otherwise, Landing Page.
  if (totalXP > 0) {
    return <Dashboard />;
  }

  return <LandingPage />;
}