import React, { useState, useEffect } from 'react';
import { useGameStore } from '../store/gameStore';
import { Timer, Zap, Flame } from 'lucide-react';
import { GAME_CONFIG } from '../config/gameConfig';

export const GameInterface: React.FC = () => {
  const [visualFeedback, setVisualFeedback] = useState<'correct' | 'incorrect' | null>(null);
  const { 
    currentProblem, timeRemaining, roundScore, roundStreak, 
    submitAnswer, tickTimer, inferredAge 
  } = useGameStore();

  const [typedAnswer, setTypedAnswer] = useState('');
  const [inputMode, setInputMode] = useState<'buttons' | 'typing'>('buttons');

  // Timer interval
  useEffect(() => {
    const timer = setInterval(() => tickTimer(), 1000);
    return () => clearInterval(timer);
  }, [tickTimer]);

  if (!currentProblem) return null;

  // Age-Adaptive UI Flags
  const isYoung = inferredAge === '6-10';
  const isOlder = inferredAge === '11-14';
  const fontClass = isYoung ? 'text-7xl md:text-9xl' : 'text-5xl md:text-7xl';
  const allowTyping = isOlder;

  const handleOptionClick = (answer: number) => {
    const isCorrect = answer === currentProblem.correctAnswer;
    setVisualFeedback(isCorrect ? 'correct' : 'incorrect');
    setTimeout(() => setVisualFeedback(null), 300);
    
    const timeSpent = GAME_CONFIG.ROUND_DURATION_SEC - timeRemaining;
    submitAnswer(answer, timeSpent);
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!typedAnswer.trim()) return;
    
    const isCorrect = Number(typedAnswer) === currentProblem.correctAnswer;
    setVisualFeedback(isCorrect ? 'correct' : 'incorrect');
    setTimeout(() => setVisualFeedback(null), 300);

    const timeSpent = GAME_CONFIG.ROUND_DURATION_SEC - timeRemaining;
    submitAnswer(Number(typedAnswer), timeSpent);
    setTypedAnswer('');
  };

  const timerColor = timeRemaining > 20 ? 'text-cyan-400' : timeRemaining > 10 ? 'text-yellow-400' : 'text-red-500 animate-pulse';

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center p-4 transition-colors duration-200 ${
      visualFeedback === 'correct' ? 'bg-green-900/60' : visualFeedback === 'incorrect' ? 'bg-red-900/60' : 'bg-gray-950'
    }`}>
      {/* HUD (Heads Up Display) */}
      <div className="w-full max-w-3xl flex justify-between items-center mb-12 p-4 bg-gray-900/80 rounded-2xl border border-gray-800 shadow-lg">
        <div className="flex items-center gap-3">
          <Flame className={`w-8 h-8 ${roundStreak > 2 ? 'text-orange-500 animate-bounce' : 'text-gray-500'}`} />
          <span className="text-2xl font-bold text-white">Streak: {roundStreak}</span>
        </div>
        <div className={`flex items-center gap-3 ${timerColor}`}>
          <Timer className="w-8 h-8" />
          <span className="text-3xl font-black">{timeRemaining}s</span>
        </div>
        <div className="flex items-center gap-3">
          <Zap className="w-8 h-8 text-cyan-400" />
          <span className="text-2xl font-bold text-white">Score: {roundScore}</span>
        </div>
      </div>

      {/* Problem Display */}
      <div className={`font-black text-white mb-12 tracking-widest drop-shadow-[0_0_20px_rgba(255,255,255,0.2)] ${fontClass}`}>
        {currentProblem.num1} {currentProblem.operation} {currentProblem.num2} = ?
      </div>

      {/* Adaptive Answer Input */}
      {allowTyping && (
        <div className="mb-6 flex gap-4 w-full max-w-md">
          <button 
            onClick={() => setInputMode('buttons')}
            className={`flex-1 py-2 rounded-lg font-bold ${inputMode === 'buttons' ? 'bg-purple-600 text-white' : 'bg-gray-800 text-gray-400'}`}
          >
            Multiple Choice
          </button>
          <button 
            onClick={() => setInputMode('typing')}
            className={`flex-1 py-2 rounded-lg font-bold ${inputMode === 'typing' ? 'bg-purple-600 text-white' : 'bg-gray-800 text-gray-400'}`}
          >
            Type Answer
          </button>
        </div>
      )}

      {inputMode === 'buttons' || !allowTyping ? (
        <div className="grid grid-cols-2 gap-4 w-full max-w-2xl">
          {currentProblem.options.map((opt, i) => (
            <button
              key={i}
              onClick={() => handleOptionClick(opt)}
              className="py-6 px-8 bg-gray-800 hover:bg-cyan-600 border-2 border-gray-700 hover:border-cyan-400 rounded-2xl text-4xl font-bold text-white transition-all transform hover:scale-105 shadow-[0_8px_0_rgb(31,41,55)] hover:shadow-[0_8px_0_rgb(8,145,178)] active:translate-y-2 active:shadow-none"
            >
              {opt} {isYoung && (opt === currentProblem.correctAnswer ? '' : '') /* Keep emojis to feedback phase for true blind test */}
            </button>
          ))}
        </div>
      ) : (
        <form onSubmit={handleFormSubmit} className="w-full max-w-md flex flex-col gap-4">
          <input
            type="number"
            autoFocus
            value={typedAnswer}
            onChange={(e) => setTypedAnswer(e.target.value)}
            className="w-full bg-gray-900 border-4 border-gray-700 focus:border-cyan-500 rounded-2xl text-center text-5xl font-bold text-white py-6 outline-none shadow-[0_0_20px_rgba(34,211,238,0.1)] transition-colors"
            placeholder="Type..."
          />
          <button 
            type="submit"
            className="w-full py-5 bg-gradient-to-r from-purple-600 to-cyan-500 rounded-2xl text-2xl font-bold text-white hover:opacity-90 transform hover:-translate-y-1 transition-all"
          >
            Submit Answer
          </button>
        </form>
      )}
    </div>
  );
};